import { expect, test } from '../fixtures';

// Starts signed out, whatever session the rest of the suite shares.
test.use({ storageState: { cookies: [], origins: [] } });

test('Login wrong password', async ({ page }) => {
  await test.step('Open the login page', async () => {
    await page.goto('/auth/login');
  });

  await test.step('Type a real username', async () => {
    await page.getByRole('textbox', { name: 'Username or Email address', exact: true }).fill('alice');
  });

  await test.step('Type a wrong password', async () => {
    await page.getByRole('textbox', { name: 'Password', exact: true }).fill('not-the-password');
  });

  await test.step('Press Login', async () => {
    await page.getByRole('button', { name: 'Login', exact: true }).click();
  });

  await test.step('The error says the username or password is wrong [code]', async () => {
    await expect(page.locator('.alert-danger')).toContainText('Wrong username or password.');
  });

  await test.step('The user stays on the login page [code]', async () => {
    await expect(page).toHaveURL(/\/auth\/login/);
  });
});
